from datetime import date, timedelta
import calendar


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]
    interval = int(parts[1])
    results = []

    def add_if_valid(year, month, day):
        try:
            candidate = date(year, month, day)
        except ValueError:
            return
        if candidate >= start_date:
            results.append(candidate)

    if kind == "DAILY":
        current = start_date
        for _ in range(count):
            results.append(current)
            current += timedelta(days=interval)

    elif kind == "WEEKLY":
        weekdays = {code: i for i, code in enumerate(
            ("MO", "TU", "WE", "TH", "FR", "SA", "SU")
        )}
        selected = sorted(weekdays[code] for code in parts[2].split(","))
        week_start = start_date - timedelta(days=start_date.weekday())
        week_index = 0

        while len(results) < count:
            active_start = week_start + timedelta(weeks=week_index * interval)
            for weekday in selected:
                candidate = active_start + timedelta(days=weekday)
                if candidate >= start_date:
                    results.append(candidate)
                    if len(results) == count:
                        break
            week_index += 1

    elif kind == "MONTHLY":
        base_year, base_month = start_date.year, start_date.month
        if len(parts) == 3:
            day_spec = int(parts[2])
            month_index = 0
            while len(results) < count:
                total_month = base_month - 1 + month_index * interval
                year = base_year + total_month // 12
                month = total_month % 12 + 1
                last_day = calendar.monthrange(year, month)[1]
                day = last_day if day_spec == -1 else day_spec
                if day <= last_day:
                    add_if_valid(year, month, day)
                month_index += 1
        else:
            occurrence = int(parts[2])
            weekday_code = parts[3]
            weekday = ("MO", "TU", "WE", "TH", "FR", "SA", "SU").index(weekday_code)
            month_index = 0
            while len(results) < count:
                total_month = base_month - 1 + month_index * interval
                year = base_year + total_month // 12
                month = total_month % 12 + 1
                first_weekday, days_in_month = calendar.monthrange(year, month)

                if occurrence == -1:
                    day = days_in_month - ((first_weekday + days_in_month - 1 - weekday) % 7)
                else:
                    day = 1 + (weekday - first_weekday) % 7 + (occurrence - 1) * 7
                if day <= days_in_month:
                    add_if_valid(year, month, day)
                month_index += 1

    elif kind == "YEARLY":
        month, day = map(int, parts[2].split("-"))
        year_index = 0
        while len(results) < count:
            year = start_date.year + year_index * interval
            add_if_valid(year, month, day)
            year_index += 1

    return [d.isoformat() for d in results]
